/* ==========================================================================
   Inspections (controlled templates, conduct, print)
   Incident & Injury Management
   ========================================================================== */
'use strict';

const INC_TYPES = ['Near Miss', 'Injury', 'Property Damage', 'Environmental'];
const SEV_LABELS = ['', '1 — Insignificant', '2 — Minor', '3 — Moderate', '4 — Major', '5 — Catastrophic'];
const RC_CATEGORIES = ['Procedure', 'Training', 'Supervision', 'PPE', 'Equipment / design', 'Inspection & maintenance', 'Risk assessment', 'Communication', 'Human factors', 'Contractor management'];
function incActions(i) { return S.actions.filter(a => a.source === 'Incident' && a.sourceId === i.id); }
function sevChip(n) { const c = n >= 4 ? 'red' : n === 3 ? 'amber' : 'green'; return badge(SEV_LABELS[n] || '—', c, true); }

ROUTES.report = (p, q) => Object.assign(incidentForm(q), { nav: 'report' });
ROUTES.incidents = (p, q) => {
  if (p[0] === 'new') return incidentForm(q);
  if (p[0]) return incidentDetail(p[0]);
  const rows = scoped('incidents').sort((a, b) => b.date.localeCompare(a.date));
  const lv = listView('inc', { rows, initial: { status: q.status || '', type: q.type || '' }, resetState: !!(q.status || q.type), search: i => [i.id, i.title, i.type, i.location, pname(i.reporter)].join(' '), href: i => '#/incidents/' + i.id, rowClass: i => i.status === 'Reported' ? 'row-red' : '',
    filters: [{ id: 'status', label: 'All statuses', options: [{ value: 'open', label: 'Open (not closed)' }, 'Reported', 'Under Investigation', 'Actions in Progress', 'Awaiting Closure', 'Closed'], test: (i, v) => v === 'open' ? i.status !== 'Closed' : i.status === v }, { id: 'type', label: 'All types', options: INC_TYPES, test: (i, v) => i.type === v }, { id: 'site', label: 'All sites', options: orgSites().map(s => ({ value: s.id, label: s.short })), test: (i, v) => i.site === v }],
    columns: [{ label: 'Incident', render: i => `<span class="mono">${i.id}</span><div class="t-title">${esc(i.title)}</div>` }, { label: 'Type', render: i => badge(i.type, i.type === 'Injury' ? 'red' : i.type === 'Environmental' ? 'green' : i.type === 'Property Damage' ? 'orange' : 'blue', true) }, { label: 'Date / site', render: i => `${fmt(i.date)} ${esc(i.time)}<div class="t-sub">${esc(sname(i.site))} · ${esc(i.location)}</div>` }, { label: 'Actual / potential', render: i => `${sevChip(i.actualSev)}<div class="mt-s">${sevChip(i.potentialSev)}</div>` }, { label: 'Investigator', render: i => i.investigator ? esc(pname(i.investigator)) : '<span class="due red">Not assigned</span>' }, { label: 'Actions', render: i => { const a = incActions(i); return a.length ? `${a.filter(x => !actionOpen(x)).length}/${a.length} verified` : '—'; } }, { label: 'Status', render: i => sbadge(i.status) }] });
  const html = `${pageHead('Incidents & injuries', 'Report near misses, injuries, property damage and environmental events; investigate root causes; drive corrective actions through verification to closure.', `<a class="btn accent" href="#/incidents/new">${icon('plus', 'sm')} Report incident</a>`, scopePill())}
    <div class="kpis">${kpi('Open incidents', rows.filter(i => i.status !== 'Closed').length, 'Not yet closed', 'amber', '#/incidents?status=open', 'alert')}${kpi('Awaiting investigation', rows.filter(i => i.status === 'Reported').length, 'Investigator to be assigned', rows.some(i => i.status === 'Reported') ? 'red' : 'green', '#/incidents?status=Reported', 'clock')}${kpi('Injuries (12 months)', rows.filter(i => i.type === 'Injury' && daysTo(i.date) > -365).length, `${rows.filter(i => i.type === 'Injury' && i.injury && i.injury.daysLost > 0).length} lost-time`, 'red', '#/incidents?type=Injury', 'alert')}${kpi('High-potential events', rows.filter(i => i.potentialSev >= 4).length, 'Potential severity major or worse', 'amber', '#/incidents', 'risk')}</div>${lv}`;
  return { title: 'Incidents', crumbs: [['Incidents & injuries', '#/incidents']], html };
};

function incidentForm(q) {
  const html = `<div class="mobile-card" style="max-width:820px">${pageHead('Report an incident', 'Quick reporting form — works on a phone in the field. Investigation details are added afterwards by the investigator.')}
  <form id="incForm" class="card" novalidate><div class="card-body" style="padding-top:16px"><div class="form-grid">
    ${fld({ name: 'type', label: 'Incident type', type: 'select', options: opts(INC_TYPES, 'Near Miss'), required: true })}
    ${fld({ name: 'title', label: 'Short title', required: true, placeholder: 'What happened, in a few words' })}
    ${fld({ name: 'date', label: 'Date', type: 'date', value: TODAY, required: true })}${fld({ name: 'time', label: 'Time', type: 'time', value: new Date().toTimeString().slice(0, 5), required: true })}
    ${fld({ name: 'site', label: 'Site / branch', type: 'select', options: siteOptions(q.asset ? byId('assets', q.asset).site : defaultSite(), false), required: true })}${fld({ name: 'location', label: 'Exact location', required: true })}
    ${fld({ name: 'person', label: 'Person involved', type: 'select', options: personOptions('') })}${fld({ name: 'others', label: 'Other persons involved (names)' })}
    ${fld({ name: 'description', label: 'What happened?', type: 'textarea', required: true, full: true, rows: 4 })}
    ${fld({ name: 'immediate', label: 'Immediate response / actions taken', type: 'textarea', required: true, full: true })}
    <fieldset class="fieldset full hidden" id="injBox"><legend>Injury details</legend><div class="form-grid">${fld({ name: 'nature', label: 'Nature of injury', placeholder: 'e.g. laceration, sprain' })}${fld({ name: 'body', label: 'Body part' })}${fld({ name: 'treatment', label: 'Treatment', type: 'select', options: opts(['First aid case', 'Medical treatment case', 'Lost time injury', 'Fatality']) })}${fld({ name: 'daysLost', label: 'Days lost (if known)', type: 'number', value: 0, min: 0 })}</div><p class="muted mt-s">${icon('lock', 'sm')} Medical details are restricted to authorised roles in production.</p></fieldset>
    ${fld({ name: 'actualSev', label: 'Actual severity', type: 'select', options: opts([1, 2, 3, 4, 5].map(n => ({ value: n, label: SEV_LABELS[n] })), 1), required: true })}${fld({ name: 'potentialSev', label: 'Potential severity (worst credible)', type: 'select', options: opts([1, 2, 3, 4, 5].map(n => ({ value: n, label: SEV_LABELS[n] })), 3), required: true })}
    ${fld({ name: 'asset', label: 'Equipment involved', type: 'select', options: opts(scoped('assets').map(a => ({ value: a.id, label: `${a.tag} — ${a.name}` })), q.asset || '', '— None —') })}${fld({ name: 'witnesses', label: 'Witnesses' })}
    <div class="field full"><label for="f_photos">Photographs / attachments</label><input id="f_photos" name="photos" type="file" multiple accept="image/*,.pdf" capture="environment"><div class="file-note">${icon('info', 'sm')} Prototype: file names only are kept as demo references.</div></div>
  </div></div><div class="modal-foot" style="border-radius:0 0 12px 12px"><a class="btn" href="${isFieldUser() ? '#/field' : '#/incidents'}">Cancel</a><button class="btn accent" type="button" data-act="incSubmit">${icon('check', 'sm')} Submit report</button></div></form></div>`;
  return { title: 'Report incident', nav: 'incidents', crumbs: [['Incidents & injuries', '#/incidents'], ['Report', '#']], html, after: () => { const t = document.querySelector('#incForm [name=type]'); const sync = () => document.getElementById('injBox').classList.toggle('hidden', t.value !== 'Injury'); t.addEventListener('change', sync); sync(); } };
}
ACT.incSubmit = () => {
  const f = document.getElementById('incForm');
  if (!validateForm(f, fail => { const d = f.querySelector('[name=date]'); if (d.value > TODAY) fail(d, 'The incident date cannot be in the future.'); if (f.querySelector('[name=type]').value === 'Injury' && !f.querySelector('[name=nature]').value.trim()) fail(f.querySelector('[name=nature]'), 'Describe the injury.'); })) return;
  const v = readForm(f); const files = [...f.querySelector('[name=photos]').files].map(fileMeta);
  const yr = v.date.slice(0, 4); let max = 0; S.incidents.forEach(i => { const m = i.id.match(new RegExp('INC-' + yr + '-(\\d+)')); if (m) max = Math.max(max, +m[1]); });
  const id = `INC-${yr}-${String(max + 1).padStart(3, '0')}`;
  const i = { id, org: siteOrgOf(v.site), type: v.type, title: v.title, date: v.date, time: v.time, site: v.site, location: v.location, reporter: S.ui.user, persons: v.person ? [v.person] : [], others: v.others, description: v.description, immediate: v.immediate, injury: v.type === 'Injury' ? { nature: v.nature, body: v.body, treatment: v.treatment, daysLost: +v.daysLost || 0 } : null, actualSev: +v.actualSev, potentialSev: +v.potentialSev, witnesses: v.witnesses, attachments: files, investigator: null, status: 'Reported', investigation: null, links: { assets: v.asset ? [v.asset] : [], docs: [] }, reporting: { required: 'To be determined', status: 'Not assessed', ref: '' }, closure: null, actions: [], history: [{ ts: nowTs(), by: S.ui.user, action: 'Incident reported', comment: '' }] };
  S.incidents.push(i);
  createIncidentAlert(i);   // draft safety alert for staff — published only after HSEQ Manager + Safety Consultant approval
  addEvent('red', 'incidents', `New incident reported: ${id}`, `${v.type} at ${sname(v.site)} — ${v.title}. Investigator to be assigned.`, '#/incidents/' + id, v.site);
  if (v.asset) { const a = byId('assets', v.asset); assetHistory(a, `Involved in incident ${id}: ${v.title}`); }
  log(`Reported ${id}: ${v.title}`, '#/incidents/' + id); save(); toast(`${id} reported. The branch manager and HSEQ team have been notified (simulated).`); navigate(isFieldUser() ? '#/field' : '#/incidents/' + id);
};

function incidentDetail(id) {
  const i = byId('incidents', id); if (!i) return ROUTES.notfound();
  const acts = incActions(i), inv = i.investigation;
  const openActs = acts.filter(actionOpen);
  const flow = ['Reported', 'Under Investigation', 'Actions in Progress', 'Awaiting Closure', 'Closed'], idx = flow.indexOf(i.status);
  const B = [];
  if (i.status === 'Reported') B.push(permBtn('incident.investigate', `<button class="btn primary" data-act="incAssign" data-id="${i.id}">Assign investigator</button>`));
  if (['Under Investigation', 'Actions in Progress'].includes(i.status)) { B.push(permBtn('incident.investigate', `<button class="btn" data-act="incInvestigate" data-id="${i.id}">${icon('search', 'sm')} Record investigation</button>`)); if (inv) B.push(permBtn('action.create', `<button class="btn primary" data-act="incAction" data-id="${i.id}">${icon('plus', 'sm')} Corrective action</button>`)); }
  if (i.status !== 'Closed' && i.status !== 'Reported') B.push(permBtn('incident.investigate', `<button class="btn success" data-act="incClose" data-id="${i.id}">${icon('checkCircle', 'sm')} Review & close</button>`));
  const html = `<div class="status-hero"><div><div class="sh-id">${i.id} · ${esc(i.type)} · ${esc(sname(i.site))}</div><h1 style="margin:2px 0 6px">${esc(i.title)}</h1><div class="btn-row">${sbadge(i.status)} Actual ${sevChip(i.actualSev)} Potential ${sevChip(i.potentialSev)}</div></div><div class="sh-actions">${B.join('')}</div></div>
  <div class="card mb"><div class="card-body" style="padding-top:12px"><div class="stepper">${flow.map((s, k) => `<div class="step ${k < idx || i.status === 'Closed' ? 'done' : k === idx ? 'current' : ''}"><span class="sd">${k < idx || i.status === 'Closed' ? '✓' : k + 1}</span><span class="sl">${s}</span></div>`).join('')}</div></div></div>
  <div class="detail"><div class="stack">
    <div class="card"><div class="card-head"><h2>Event details</h2></div><div class="card-body"><div class="kv">
      <div>Incident number</div><div class="mono">${i.id}</div><div>Type</div><div>${esc(i.type)}</div><div>Date & time</div><div>${fmt(i.date)} ${esc(i.time)}</div><div>Organisation / branch</div><div>${esc(orgOf(i.org).short)} · ${esc(site(i.site).name)}</div><div>Location</div><div>${esc(i.location)}</div>
      <div>Reported by</div><div>${esc(pname(i.reporter))}</div><div>Persons involved</div><div>${i.persons.map(x => esc(pname(x))).join(', ') || '—'}${i.others ? ', ' + esc(i.others) : ''}</div>
      <div>Description</div><div>${esc(i.description)}</div><div>Immediate response</div><div>${esc(i.immediate)}</div><div>Witnesses</div><div>${esc(i.witnesses || '—')}</div>
      <div>Attachments</div><div>${i.attachments.length ? i.attachments.map(fileChip).join(' ') : '—'}</div>
    </div></div></div>
    ${i.injury ? `<div class="card"><div class="card-head"><h2>${icon('lock', 'sm')} Injury details</h2><span class="ch-sub">Restricted personal information</span></div><div class="card-body">${can('incident.investigate') ? `<div class="kv"><div>Nature of injury</div><div>${esc(i.injury.nature)}</div><div>Body part</div><div>${esc(i.injury.body)}</div><div>Treatment</div><div>${esc(i.injury.treatment)}</div><div>Days lost</div><div>${i.injury.daysLost}</div></div>` : `<p class="muted">${icon('lock', 'sm')} Visible to investigators and HSEQ roles only.</p>`}</div></div>` : ''}
    <div class="card"><div class="card-head"><h2>Investigation & root-cause analysis</h2>${i.investigator ? `<span class="ch-sub">Investigator: ${esc(pname(i.investigator))}</span>` : ''}</div><div class="card-body">${inv ? `<div class="kv"><div>Findings</div><div>${esc(inv.findings)}</div><div>Immediate cause</div><div>${esc(inv.immediate)}</div><div>Underlying cause</div><div>${esc(inv.underlying)}</div><div>Root cause</div><div><b>${esc(inv.root)}</b></div><div>Cause categories</div><div>${(inv.categories || []).map(c => `<span class="tag">${esc(c)}</span>`).join(' ')}</div><div>Completed</div><div>${inv.completed ? fmt(inv.completed) : '<span class="due amber">In progress</span>'}</div></div>` : `<p class="muted">${i.investigator ? 'Investigation not yet recorded.' : 'No investigator assigned yet.'}</p>`}</div></div>
    <div class="card"><div class="card-head"><h2>Corrective actions</h2>${inv ? permBtn('action.create', `<button class="btn sm" data-act="incAction" data-id="${i.id}">Add</button>`) : ''}</div><div class="card-body flush">${actionsMiniTable(acts)}</div></div>
    <div class="card"><div class="card-head"><h2>History</h2></div><div class="card-body"><ul class="timeline">${i.history.slice().reverse().map(h => `<li><b>${esc(h.action)}</b><div class="tl-meta">${esc(pname(h.by))} · ${fmtTs(h.ts)}</div>${h.comment ? `<div class="tl-comment">${esc(h.comment)}</div>` : ''}</li>`).join('')}${i.closure ? `<li class="t-green"><b>Closed</b><div class="tl-meta">${esc(pname(i.closure.by))} · ${fmt(i.closure.date)}</div>${i.closure.comment ? `<div class="tl-comment">${esc(i.closure.comment)}</div>` : ''}</li>` : ''}</ul></div></div>
  </div><div class="stack">
    <div class="card"><div class="card-head"><h2>External reporting</h2>${permBtn('incident.investigate', `<button class="btn sm" data-act="incReporting" data-id="${i.id}">Update</button>`)}</div><div class="card-body"><div class="kv"><div>Reportable?</div><div>${esc(i.reporting.required)}</div><div>Status</div><div>${esc(i.reporting.status)}</div><div>Reference</div><div>${esc(i.reporting.ref || '—')}</div></div><p class="muted mt-s">Whether an incident must be reported to the authorities (e.g. under section 24 of the OHS Act or COIDA) must be determined by a competent person.</p></div></div>
    ${incidentAlertCard(i)}
    <div class="card"><div class="card-head"><h2>Linked records</h2>${permBtn('incident.investigate', `<button class="btn sm" data-act="incLink" data-id="${i.id}">Link</button>`)}</div><div class="card-body"><ul class="link-list">
      ${i.links.assets.map(x => { const a = byId('assets', x); return `<li><div class="ll-main"><a href="#/assets/${a.id}">${esc(a.tag)}</a><div>Asset · ${esc(a.name)}</div></div>${sbadge(a.status)}</li>`; }).join('')}
      ${i.links.docs.map(x => { const d = byId('documents', x); return `<li><div class="ll-main"><a href="#/documents/${d.id}">${esc(d.number)}</a><div>Procedure · ${esc(d.title)}</div></div>${sbadge(docStatus(d))}</li>`; }).join('')}
      ${!i.links.assets.length && !i.links.docs.length ? '<li class="muted">No links yet.</li>' : ''}
    </ul></div></div>
    ${i.status === 'Awaiting Closure' ? `<div class="alert success">${icon('checkCircle')}<div>All corrective actions are verified. Review the investigation and close the incident.</div></div>` : openActs.length ? `<div class="alert info">${icon('info')}<div>${openActs.length} corrective action(s) still open. The incident cannot be closed until all actions are verified.</div></div>` : ''}
  </div></div>`;
  return { title: i.id, nav: 'incidents', crumbs: [['Incidents & injuries', '#/incidents'], [i.id, '#']], html };
}
ACT.incAssign = (el) => { const i = byId('incidents', el.dataset.id); openModal({ title: 'Assign investigator', sub: i.id, body: `<div class="form-grid">${fld({ name: 'inv', label: 'Investigation owner', type: 'select', options: personOptions(site(i.site).manager, p => !!p.sysRole), required: true })}${fld({ name: 'due', label: 'Investigation due', type: 'date', value: addDays(TODAY, 7), required: true })}</div>`, buttons: [{ label: 'Assign & start investigation', cls: 'primary', onClick: m => { if (!validateForm(m)) return false; const v = readForm(m); i.investigator = v.inv; i.status = 'Under Investigation'; i.invDue = v.due; i.history.push({ ts: nowTs(), by: S.ui.user, action: `Investigation assigned to ${pname(v.inv)} (due ${fmt(v.due)})`, comment: '' }); addEvent('amber', 'incidents', `Investigation assigned: ${i.id}`, `${pname(v.inv)} to investigate "${i.title}".`, '#/incidents/' + i.id, i.site); log(`Assigned investigation of ${i.id}`, '#/incidents/' + i.id); save(); toast('Investigator assigned.'); rerender(); } }] }); };
ACT.incInvestigate = (el) => {
  const i = byId('incidents', el.dataset.id), inv = i.investigation || {};
  openModal({ title: 'Record investigation', sub: `${i.id} — use the "5 whys" to move from the immediate cause to the root cause.`, size: 'wide', body: `<div class="form-grid">
    ${fld({ name: 'findings', label: 'Investigation findings', type: 'textarea', value: inv.findings || '', required: true, full: true })}
    ${fld({ name: 'immediate', label: 'Immediate cause (what directly caused it?)', type: 'textarea', value: inv.immediate || '', required: true, full: true, rows: 2 })}
    ${fld({ name: 'underlying', label: 'Underlying cause (why did that happen?)', type: 'textarea', value: inv.underlying || '', required: true, full: true, rows: 2 })}
    ${fld({ name: 'root', label: 'Root cause (system failure that allowed it)', type: 'textarea', value: inv.root || '', required: true, full: true, rows: 2 })}
    <div class="field full"><label>Cause categories</label><div class="grid g3">${RC_CATEGORIES.map(c => `<label class="check"><input type="checkbox" name="cat_${c}" ${(inv.categories || []).includes(c) ? 'checked' : ''}> ${esc(c)}</label>`).join('')}</div></div>
    ${fld({ name: 'complete', label: 'Investigation complete — proceed to corrective actions', type: 'checkbox', value: !!inv.completed, full: true })}</div>`,
    buttons: [{ label: 'Save investigation', cls: 'primary', onClick: m => { if (!validateForm(m)) return false; const v = readForm(m); const cats = RC_CATEGORIES.filter(c => v['cat_' + c]);
      i.investigation = { findings: v.findings, immediate: v.immediate, underlying: v.underlying, root: v.root, categories: cats, completed: v.complete ? TODAY : null };
      i.history.push({ ts: nowTs(), by: S.ui.user, action: v.complete ? 'Investigation completed — root cause identified' : 'Investigation updated', comment: 'Root cause: ' + v.root });
      if (v.complete && i.status === 'Under Investigation') i.status = 'Actions in Progress';
      log(`Investigation ${v.complete ? 'completed' : 'updated'} for ${i.id}`, '#/incidents/' + i.id); save(); toast(v.complete ? 'Investigation complete. Now raise corrective actions for the root causes.' : 'Investigation saved.'); rerender();
      if (v.complete && !incActions(i).length) setTimeout(() => ACT.incAction({ dataset: { id: i.id } }), 60);
    } }] });
};
ACT.incAction = (el) => { const i = byId('incidents', el.dataset.id); raiseActionModal({ source: 'Incident', sourceId: i.id, title: `${i.id}: ${i.investigation ? i.investigation.root : i.title}`, site: i.site, owner: i.investigator, priority: i.potentialSev >= 4 ? 'High' : 'Medium' }, a => { if (!i.actions.includes(a.id)) i.actions.push(a.id); if (i.status === 'Under Investigation' || i.status === 'Awaiting Closure') i.status = 'Actions in Progress'; i.history.push({ ts: nowTs(), by: S.ui.user, action: `Corrective action ${a.id} raised`, comment: a.title }); save(); rerender(); }); };
ACT.incClose = (el) => { const i = byId('incidents', el.dataset.id); const open = incActions(i).filter(actionOpen);
  if (!i.investigation || !i.investigation.completed) { toast('Complete the investigation before closing.', 'error'); return; }
  if (open.length) { toast(`Cannot close: ${open.length} corrective action(s) not yet verified (${open.map(a => a.id).join(', ')}).`, 'error'); return; }
  openModal({ title: 'Review & close incident', sub: i.id, body: fld({ name: 'comment', label: 'Closure review comments', type: 'textarea', required: true }), buttons: [{ label: 'Close incident', cls: 'success', onClick: m => { if (!validateForm(m)) return false; i.status = 'Closed'; i.closure = { by: S.ui.user, date: TODAY, comment: readForm(m).comment }; log(`Closed ${i.id}`, '#/incidents/' + i.id); save(); toast(`${i.id} closed.`); rerender(); } }] }); };
ACT.incReporting = (el) => { const i = byId('incidents', el.dataset.id); openModal({ title: 'External reporting status', sub: i.id, body: `<div class="form-grid">${fld({ name: 'required', label: 'Reportable to authorities?', type: 'select', options: opts(['To be determined', 'Yes', 'No'], i.reporting.required) })}${fld({ name: 'status', label: 'Status', value: i.reporting.status })}${fld({ name: 'ref', label: 'Reference', value: i.reporting.ref })}</div>`, buttons: [{ label: 'Save', cls: 'primary', onClick: m => { i.reporting = readForm(m); i.history.push({ ts: nowTs(), by: S.ui.user, action: 'Reporting status updated: ' + i.reporting.status, comment: '' }); save(); rerender(); } }] }); };
ACT.incLink = (el) => { const i = byId('incidents', el.dataset.id); const list = [].concat(scoped('assets').map(a => ({ value: 'assets|' + a.id, label: `Asset ${a.tag}` })), scoped('documents').filter(docActive).map(d => ({ value: 'docs|' + d.id, label: `Procedure ${d.number} — ${d.title}` })));
  openModal({ title: 'Link record', sub: i.id, body: fld({ name: 'ref', label: 'Record', type: 'select', options: opts(list, '', '— Select —'), required: true }), buttons: [{ label: 'Link', cls: 'primary', onClick: m => { if (!validateForm(m)) return false; const [k, id] = readForm(m).ref.split('|'); if (!i.links[k].includes(id)) i.links[k].push(id); save(); toast('Linked.'); rerender(); } }] }); };

/* ==========================================================================
   AUDITS & INSPECTIONS
   ========================================================================== */
function tplCurrent(t) { return t.revisions.find(r => r.status === 'Approved'); }
function inspectionsPage(tab, q) {
  const sch = scoped('schedules').sort((a, b) => a.nextDue.localeCompare(b.nextDue));
  const ins = scoped('inspections').sort((a, b) => b.date.localeCompare(a.date));
  const tabs = [['schedule', 'Inspection schedule', sch.filter(s => daysTo(s.nextDue) < 0).length || '', 'red'], ['records', 'Inspection records', ins.length], ['templates', 'Checklist templates', S.templates.length]];
  let body = '', act = '';
  if (tab === 'schedule') { act = permBtn('inspect', `<button class="btn primary" data-act="schedNew">${icon('plus', 'sm')} New inspection schedule</button>`); const rows = q.due === 'overdue' ? sch.filter(s => daysTo(s.nextDue) < 0) : sch; body = `${q.due === 'overdue' ? `<div class="mb"><span class="active-filter">Overdue only <button data-act="go" data-href="#/inspections/schedule" aria-label="Clear">${icon('x', 'sm')}</button></span></div>` : ''}<div class="card"><div class="card-body flush"><table class="tbl stackable"><thead><tr><th>Inspection</th><th>Asset / area</th><th>Site</th><th>Frequency</th><th>Next due</th><th>Assigned</th><th></th></tr></thead><tbody>${rows.map(s => { const t = byId('templates', s.template); return `<tr class="${daysTo(s.nextDue) < 0 ? 'row-red' : ''}"><td data-label="Inspection"><b>${esc(t.title)}</b><div class="t-sub">${esc(t.docNumber)} Rev ${tplCurrent(t).rev}</div></td><td data-label="Target">${s.asset ? `<a href="#/assets/${s.asset}">${esc(s.target)}</a>` : esc(s.target)}</td><td data-label="Site">${esc(sname(s.site))}</td><td data-label="Frequency">Every ${s.freqDays} days</td><td data-label="Next due">${dueText(s.nextDue)}</td><td data-label="Assigned">${esc(pname(s.assignee))}</td><td data-label="">${can('inspect') ? `<a class="btn sm primary" href="#/inspect/${s.id}">Start</a>` : ''}</td></tr>`; }).join('')}</tbody></table></div></div>`; }
  if (tab === 'records') body = `<div class="card"><div class="card-body flush">${inspTable(ins)}</div></div>`;
  if (tab === 'templates') body = templatesHtml();
  const fails = ins.filter(i => daysTo(i.date) > -90).reduce((n, i) => n + i.results.filter(r => r.result === 'Fail').length, 0);
  const html = `${pageHead('Inspections', 'Scheduled checklist inspections of assets and work areas. Failed items raise defects and corrective actions; a critical failure takes the asset out of service. Reports print with the controlled template header.', act, scopePill())}
    <div class="kpis">${kpi('Inspections overdue', sch.filter(s => daysTo(s.nextDue) < 0).length, `${sch.length} scheduled`, sch.some(s => daysTo(s.nextDue) < 0) ? 'red' : 'green', '#/inspections/schedule?due=overdue', 'clipboard')}${kpi('Due in 7 days', sch.filter(s => daysTo(s.nextDue) >= 0 && daysTo(s.nextDue) <= 7).length, 'Upcoming inspections', 'amber', '#/inspections/schedule', 'clock')}${kpi('Completed (90 days)', ins.filter(i => daysTo(i.date) > -90).length, `${fails} failed item(s) found`, 'blue', '#/inspections/records', 'checkCircle')}${kpi('Actions from inspections', S.actions.filter(a => inScope(a) && a.source === 'Inspection' && actionOpen(a)).length, 'Open corrective actions', 'amber', '#/actions?source=Inspection', 'target')}</div>
    ${tabsHtml('#/inspections', tabs, tab)}${body}`;
  return { title: 'Inspections', nav: 'inspections', crumbs: [['Inspections', '#/inspections']], html };
}
function templatesHtml() {
  return `<div class="alert info">${icon('lock')}<div>Templates are <b>controlled documents</b>. The header (logo, title, document number, revision) comes from the approved revision and cannot be edited by inspectors. Completed inspections keep the revision used at the time.</div></div>` + S.templates.map(t => { const cur = tplCurrent(t), draft = t.revisions.find(r => r.status === 'Draft'); return `<div class="card"><div class="card-head"><div><h2>${esc(t.title)}</h2><span class="ch-sub mono">${esc(t.docNumber)} · ${esc(t.scope)}</span>${t.procedure && byId('documents', t.procedure) ? `<div class="ch-sub">Related procedure: <a href="#/documents/${t.procedure}">${esc(byId('documents', t.procedure).number)} — ${esc(byId('documents', t.procedure).title)}</a></div>` : ''}</div><div class="btn-row">${sbadge('Approved')} <span class="tag">Current: Rev ${cur.rev} (${fmt(cur.revDate)})</span>${draft ? permBtn('doc.approve', `<button class="btn sm success" data-act="tplApprove" data-id="${t.id}">Approve Rev ${draft.rev}</button>`) : permBtn('doc.create', `<button class="btn sm" data-act="tplRevise" data-id="${t.id}">Create new revision</button>`)}</div></div><div class="card-body"><div class="grid g2"><div><h4>Checklist (Rev ${cur.rev})</h4><ol style="margin:6px 0 0;padding-left:18px">${cur.questions.map(q => `<li style="margin-bottom:3px">${esc(q.text)} ${q.critical ? badge('Critical', 'red', true) : ''}</li>`).join('')}</ol></div><div><h4>Revision history</h4><ul class="link-list">${t.revisions.slice().reverse().map(r => `<li><div class="ll-main"><b>Rev ${r.rev}</b><div>${fmt(r.revDate)} · ${r.approvedBy ? 'approved by ' + esc(pname(r.approvedBy)) : 'not approved'}${r.changeNote ? ' · ' + esc(r.changeNote) : ''}</div></div>${sbadge(r.status)}</li>`).join('')}</ul><p class="muted">Used in ${S.inspections.filter(i => i.template.templateId === t.id).length} inspection record(s).</p></div></div></div></div>`; }).join('');
}
ACT.tplRevise = (el) => { const t = byId('templates', el.dataset.id), cur = tplCurrent(t); openModal({ title: 'Create new template revision', sub: `${t.docNumber} — Rev ${cur.rev + 1} (draft). Rev ${cur.rev} stays in use until approved.`, size: 'wide', body: `<div class="form-grid">${fld({ name: 'questions', label: 'Checklist questions (one per line; start a line with ! to mark it critical)', type: 'textarea', rows: 10, required: true, full: true, value: cur.questions.map(q => (q.critical ? '!' : '') + q.text).join('\n') })}${fld({ name: 'note', label: 'Change note', required: true, full: true })}</div>`,
  buttons: [{ label: 'Save draft revision', cls: 'primary', onClick: m => { if (!validateForm(m)) return false; const v = readForm(m); const qs = v.questions.split('\n').map(x => x.trim()).filter(Boolean).map((x, k) => ({ id: 'q' + (k + 1), text: x.replace(/^!/, '').trim(), critical: x.startsWith('!') })); t.revisions.push({ rev: cur.rev + 1, revDate: TODAY, status: 'Draft', approvedBy: null, changeNote: v.note, questions: qs }); log(`Draft revision ${cur.rev + 1} of ${t.docNumber}`, '#/inspections/templates'); save(); toast('Draft revision saved — approval required before use.'); rerender(); } }] }); };
ACT.tplApprove = (el) => { const t = byId('templates', el.dataset.id), d = t.revisions.find(r => r.status === 'Draft'); confirmBox('Approve template revision', `Approve ${esc(t.docNumber)} Rev ${d.rev}? New inspections will use this revision; historical inspections keep their original revision.`, 'Approve', () => { t.revisions.forEach(r => { if (r.status === 'Approved') r.status = 'Superseded'; }); d.status = 'Approved'; d.approvedBy = S.ui.user; d.approvedOn = TODAY; d.revDate = TODAY; log(`Approved ${t.docNumber} Rev ${d.rev}`, '#/inspections/templates'); save(); toast(`Rev ${d.rev} approved.`); rerender(); }, 'success'); };
ACT.schedNew = () => openModal({ title: 'New inspection schedule', body: `<div class="form-grid">${fld({ name: 'template', label: 'Template', type: 'select', options: opts(S.templates.map(t => ({ value: t.id, label: `${t.docNumber} — ${t.title}` })), '', '— Select —'), required: true, full: true })}${fld({ name: 'asset', label: 'Asset (optional)', type: 'select', options: opts(scoped('assets').map(a => ({ value: a.id, label: a.tag })), '', '— Site / area inspection —') })}${fld({ name: 'target', label: 'Area (if no asset)' })}${fld({ name: 'site', label: 'Site', type: 'select', options: siteOptions(defaultSite(), false), required: true })}${fld({ name: 'freqDays', label: 'Frequency (days)', type: 'number', value: 30, min: 1, required: true })}${fld({ name: 'nextDue', label: 'First due', type: 'date', value: TODAY, required: true })}${fld({ name: 'assignee', label: 'Assigned inspector', type: 'select', options: personOptions(''), required: true })}</div>`,
  buttons: [{ label: 'Create schedule', cls: 'primary', onClick: m => { if (!validateForm(m, fail => { if (!m.querySelector('[name=asset]').value && !m.querySelector('[name=target]').value.trim()) fail(m.querySelector('[name=target]'), 'Enter an area or choose an asset.'); })) return false; const v = readForm(m); const a = v.asset && byId('assets', v.asset); S.schedules.push({ id: nextId('ISCH-', 'schedules', 2), template: v.template, asset: v.asset || null, site: a ? a.site : v.site, target: a ? a.tag : v.target, freqDays: +v.freqDays, nextDue: v.nextDue, assignee: v.assignee }); save(); toast('Schedule created.'); rerender(); } }] });

/* ---------------- Conduct an inspection (mobile-first) ---------------- */
const INSP = { sched: null, answers: {} };
ROUTES.inspect = (p) => {
  const s = byId('schedules', p[0]); if (!s) return ROUTES.notfound();
  const t = byId('templates', s.template), r = tplCurrent(t), a = s.asset && byId('assets', s.asset);
  if (INSP.sched !== s.id) { INSP.sched = s.id; INSP.answers = {}; }
  if (isFieldUser() && (!can('inspect.qr') || !s.asset || QR_ACCESS.asset !== s.asset)) return { title: 'Inspection', nav: 'field', crumbs: [['Home', '#/field'], ['Inspection', '#']], html: `<div class="mobile-card"><div class="alert info">${icon('qr')}<div><b>Scan the asset's QR code to start this inspection.</b> Field users start inspections from the asset's QR page.</div></div><button class="btn primary" data-act="qrScan">${icon('qr', 'sm')} Scan asset QR code</button></div>` };
  if (!can('inspect') && !isFieldUser()) return { title: 'Inspection', nav: 'inspections', crumbs: [['Inspections', '#/inspections'], ['Inspection', '#']], html: `<div class="alert danger">${icon('lock')}<div>${esc(noPerm('inspect'))}</div></div>` };
  const html = `<div class="mobile-card" style="max-width:860px">
    ${a && a.status === 'Out of Service' ? `<div class="alert danger">${icon('alert')}<div><b>${esc(a.tag)} is out of service.</b> You may still record an inspection (e.g. post-repair check).</div></div>` : ''}
    <div class="controlled-header"><div class="chh"><div class="print-logo"><div class="logo-mark">VDW</div><div><b style="font-size:12px">${esc(orgOf(S.ui.org).short)}</b><small>HSEQ Management System</small></div></div><div class="ch-title">${esc(t.title)}</div><div class="ch-meta">Doc no: <b class="mono">${esc(t.docNumber)}</b><br>Revision: <b>${r.rev}</b> · Rev. date: <b>${fmt(r.revDate)}</b><br>Status: Approved (${esc(pname(r.approvedBy))})</div></div>
      <div class="ch-lock">${icon('lock', 'sm')} Controlled header from the approved template — not editable during inspections.</div></div>
    <div class="card mb"><div class="card-body" style="padding-top:14px"><div class="kv"><div>Asset / area</div><div><b>${esc(s.target)}</b>${a ? ` · ${esc(a.name)} · S/N ${esc(a.serial)}` : ''}</div><div>Site</div><div>${esc(site(s.site).name)}</div><div>Schedule</div><div>${s.id} · every ${s.freqDays} days · due ${dueText(s.nextDue)}</div><div>Inspector</div><div>${esc(pname(S.ui.user))} (signed-in demo user)</div></div>
      <div class="form-grid mt-s">${fld({ name: 'idate', label: 'Inspection date', type: 'date', value: TODAY, required: true })}</div></div></div>
    <h4 class="mb">Checklist — ${r.questions.length} items <span class="muted" id="answered" style="text-transform:none;letter-spacing:0"></span></h4>
    <div id="qList">${r.questions.map((q, k) => qCard(q, k, a)).join('')}</div>
    <div class="card mt"><div class="card-body" style="padding-top:14px"><div class="form-grid">${fld({ name: 'summary', label: 'General findings / comments', type: 'textarea', full: true })}${fld({ name: 'reviewer', label: 'Reviewer (sign-off)', type: 'select', options: personOptions(site(s.site).manager, x => !!x.sysRole) })}${fld({ name: 'declare', label: 'I declare that this inspection was carried out as recorded.', type: 'checkbox', full: true })}</div></div>
      <div class="modal-foot" style="border-radius:0 0 12px 12px"><a class="btn" href="${isFieldUser() && a ? '#/qr/' + a.id : a ? '#/assets/' + a.id : '#/inspections/schedule'}">Cancel</a><button class="btn primary" data-act="inspSubmit">${icon('check', 'sm')} Submit inspection</button></div></div>
  </div>`;
  return { title: 'Inspection — ' + s.target, nav: 'inspections', crumbs: [['Inspections', '#/inspections'], ['Inspection: ' + s.target, '#']], html, after: updAnswered };
};
function qCard(q, k, a) {
  const ans = INSP.answers[q.id] || {};
  return `<div class="q-card ${ans.result === 'Fail' ? 'failed' : ''}" id="qc-${q.id}"><div class="q-top"><div class="q-text"><span class="q-num">${k + 1}.</span>${esc(q.text)} ${q.critical ? badge('Critical item', 'red', true) : ''}</div>
    <div class="seg" role="group" aria-label="Response for item ${k + 1}">${['Pass', 'Fail', 'N/A'].map(x => `<button type="button" class="${ans.result === x ? 'on-' + (x === 'N/A' ? 'na' : x.toLowerCase()) : ''}" data-act="qAns" data-q="${q.id}" data-v="${x}" aria-pressed="${ans.result === x}">${x}</button>`).join('')}</div></div>
    <div class="q-extra"><div class="field"><label for="c-${q.id}">Comment${ans.result === 'Fail' ? '<span class="req">*</span>' : ''}</label><input type="text" id="c-${q.id}" data-qc="${q.id}" value="${esc(ans.comment || '')}" placeholder="${ans.result === 'Fail' ? 'Describe the failure' : 'Optional'}"></div><div class="field"><label for="ph-${q.id}">Photo</label><input type="file" id="ph-${q.id}" data-qp="${q.id}" accept="image/*" capture="environment"></div></div>
    ${ans.result === 'Fail' ? `<div class="q-fail"><label class="check"><input type="checkbox" data-qf="${q.id}" data-k="raise" ${ans.raise !== false ? 'checked' : ''}> <span><b>Raise corrective action</b> in the central register</span></label>
      <div class="form-grid mt-s"><div class="field"><label>Action owner</label><select data-qf="${q.id}" data-k="owner">${personOptions(ans.owner || (a ? a.responsible : byId('schedules', INSP.sched).assignee), canOwnActions)}</select></div><div class="field"><label>Priority</label><select data-qf="${q.id}" data-k="priority">${opts(S.config.priorities.map(p => p.name), ans.priority || (q.critical ? 'Critical' : 'High'))}</select></div></div>
      ${a ? `<label class="check mt-s"><input type="checkbox" data-qf="${q.id}" data-k="oos" ${ans.oos ? 'checked' : ''}> <span style="color:var(--red)"><b>Critical defect — remove ${esc(a.tag)} from service</b></span></label>` : ''}</div>` : ''}
  </div>`;
}
function updAnswered() { const t = byId('templates', byId('schedules', INSP.sched).template), n = tplCurrent(t).questions.length, c = Object.values(INSP.answers).filter(x => x.result).length; const el = document.getElementById('answered'); if (el) el.textContent = `· ${c} of ${n} answered`; }
ACT.qAns = (el) => {
  const q = el.dataset.q, s = byId('schedules', INSP.sched), t = byId('templates', s.template), r = tplCurrent(t), k = r.questions.findIndex(x => x.id === q), qq = r.questions[k];
  const ans = INSP.answers[q] = INSP.answers[q] || {}; ans.result = el.dataset.v;
  if (ans.result === 'Fail' && ans.oos == null) ans.oos = !!qq.critical && !!s.asset;
  const card = document.getElementById('qc-' + q); card.outerHTML = qCard(qq, k, s.asset && byId('assets', s.asset)); updAnswered();
};
document.addEventListener('input', e => { const t = e.target; if (t.dataset && t.dataset.qc) { (INSP.answers[t.dataset.qc] = INSP.answers[t.dataset.qc] || {}).comment = t.value; } });
document.addEventListener('change', e => { const t = e.target; if (!t.dataset) return; if (t.dataset.qp) { (INSP.answers[t.dataset.qp] = INSP.answers[t.dataset.qp] || {}).photo = fileMeta(t.files[0]); } if (t.dataset.qf) { const a = INSP.answers[t.dataset.qf] = INSP.answers[t.dataset.qf] || {}; a[t.dataset.k] = t.type === 'checkbox' ? t.checked : t.value; } });
ACT.inspSubmit = () => {
  const s = byId('schedules', INSP.sched), t = byId('templates', s.template), r = tplCurrent(t), a = s.asset && byId('assets', s.asset);
  const root = document.getElementById('content');
  const missing = r.questions.filter(q => !(INSP.answers[q.id] || {}).result);
  if (missing.length) { toast(`Answer all checklist items (${missing.length} outstanding).`, 'error'); document.getElementById('qc-' + missing[0].id).scrollIntoView({ behavior: 'smooth', block: 'center' }); return; }
  const noComment = r.questions.filter(q => INSP.answers[q.id].result === 'Fail' && !(INSP.answers[q.id].comment || '').trim());
  if (noComment.length) { toast('Every failed item needs a comment describing the failure.', 'error'); const inp = document.getElementById('c-' + noComment[0].id); inp.closest('.field').classList.add('invalid'); inp.focus(); return; }
  if (!root.querySelector('[name=declare]').checked) { toast('Please confirm the inspector declaration.', 'error'); return; }
  const v = readForm(root);
  const id = nextId('INS-', 'inspections', 4, 1000);
  const snap = { templateId: t.id, docNumber: t.docNumber, title: t.title, rev: r.rev, revDate: r.revDate, questions: JSON.parse(JSON.stringify(r.questions)) };
  const ins = { id, template: snap, schedule: s.id, asset: s.asset, site: s.site, target: s.target, date: v.idate || TODAY, inspector: S.ui.user, reviewer: v.reviewer || null, results: r.questions.map(q => ({ qid: q.id, result: INSP.answers[q.id].result, comment: INSP.answers[q.id].comment || '', photo: INSP.answers[q.id].photo || null })), summary: v.summary, actions: [], status: 'Completed', defects: [] };
  S.inspections.push(ins);
  let oos = false;
  r.questions.forEach(q => { const an = INSP.answers[q.id]; if (an.result !== 'Fail') return;
    let d = null; if (a) { d = createDefect(a, `${q.text}: ${an.comment}`, an.oos ? 'Critical' : q.critical ? 'Major' : 'Minor', an.oos, id); ins.defects.push(d.id); if (an.oos) oos = true; }
    if (an.raise !== false) { const act = createAction({ source: 'Inspection', sourceId: id, title: `${s.target}: ${q.text} — failed`, action: an.comment, owner: an.owner || (a ? a.responsible : s.assignee), priority: an.priority || (q.critical ? 'Critical' : 'High'), site: s.site }); ins.actions.push(act.id); if (d) { d.action = act.id; d.status = 'Action Raised'; } }
  });
  const prev = s.nextDue; s.nextDue = addDays(ins.date, s.freqDays); s.lastDone = ins.date;
  if (a) assetHistory(a, `Inspection ${id} completed on ${t.docNumber} Rev ${r.rev} — ${ins.results.filter(x => x.result === 'Fail').length} failed item(s); next inspection ${fmt(s.nextDue)}`);
  log(`Completed inspection ${id} (${s.target}) — ${ins.actions.length} action(s) raised`, '#/inspections/' + id);
  INSP.sched = null; INSP.answers = {}; save();
  toast(`${id} submitted. ${ins.actions.length ? ins.actions.length + ' corrective action(s) raised. ' : ''}${oos ? `<b>${esc(a.tag)} placed OUT OF SERVICE.</b> ` : ''}Next inspection scheduled ${fmt(s.nextDue)} (was ${fmt(prev)}).`);
  navigate(isFieldUser() ? (s.asset ? '#/qr/' + s.asset : '#/field') : '#/inspections/' + id);
};

ROUTES.inspections = function (p) {
  if (!p[0] || !/^INS-/.test(p[0])) return inspectionsPage(p[0] || 'schedule', arguments[1] || {});
  const i = byId('inspections', p[0]); if (!i) return ROUTES.notfound();
  const fails = i.results.filter(r => r.result === 'Fail');
  const html = `<div class="status-hero"><div><div class="sh-id">${i.id} · ${esc(sname(i.site))}</div><h1 style="margin:2px 0 6px">${esc(i.template.title)} — ${esc(i.target)}</h1><div class="btn-row">${sbadge(i.status)} <span class="tag">${esc(i.template.docNumber)} Rev ${i.template.rev}</span> ${fails.length ? badge(fails.length + ' failed item(s)', 'red') : badge('All items passed', 'green')}</div></div><div class="sh-actions">${i.status === 'Completed' ? permBtn('action.verify', `<button class="btn" data-act="inspReview" data-id="${i.id}">${icon('check', 'sm')} Review & sign off</button>`) : ''}<a class="btn primary" href="#/print/${i.id}">${icon('print', 'sm')} Controlled report / print</a></div></div>
  ${(() => { const t = byId('templates', i.template.templateId); const cur = t && tplCurrent(t); return cur && cur.rev !== i.template.rev ? `<div class="alert info">${icon('info')}<div>This inspection was performed on <b>Rev ${i.template.rev}</b> of ${esc(i.template.docNumber)}. The current approved revision is Rev ${cur.rev}; the historical record retains the revision used at the time.</div></div>` : ''; })()}
  <div class="detail"><div class="stack"><div class="card"><div class="card-head"><h2>Checklist results</h2></div><div class="card-body flush"><table class="tbl stackable"><thead><tr><th>#</th><th>Item</th><th>Result</th><th>Comment / evidence</th></tr></thead><tbody>${i.template.questions.map((q, k) => { const r = i.results.find(x => x.qid === q.id) || {}; return `<tr class="${r.result === 'Fail' ? 'row-red' : ''}"><td data-label="#">${k + 1}</td><td data-label="Item">${esc(q.text)} ${q.critical ? badge('Critical', 'red', true) : ''}</td><td data-label="Result"><span class="${r.result === 'Pass' ? 'res-pass' : r.result === 'Fail' ? 'res-fail' : 'res-na'}">${esc(r.result || '—')}</span></td><td data-label="Comment">${esc(r.comment || '')}${r.photo ? `<div class="mt-s">${fileChip(r.photo)}</div>` : ''}</td></tr>`; }).join('')}</tbody></table></div></div>
    ${i.summary ? `<div class="card"><div class="card-head"><h2>Findings / comments</h2></div><div class="card-body">${esc(i.summary)}</div></div>` : ''}</div>
  <div class="stack"><div class="card"><div class="card-head"><h2>Inspection details</h2></div><div class="card-body"><div class="kv"><div>Date</div><div>${fmt(i.date)}</div><div>Asset / area</div><div>${i.asset ? `<a href="#/assets/${i.asset}">${esc(i.target)}</a>` : esc(i.target)}</div><div>Inspector</div><div>${esc(pname(i.inspector))}</div><div>Reviewer</div><div>${esc(pname(i.reviewer))}${i.reviewedOn ? ' · ' + fmt(i.reviewedOn) : ''}</div><div>Template</div><div>${esc(i.template.docNumber)} Rev ${i.template.rev} (${fmt(i.template.revDate)})</div></div></div></div>
    <div class="card"><div class="card-head"><h2>Corrective actions</h2></div><div class="card-body">${i.actions.length ? `<ul class="link-list">${i.actions.map(x => { const a = byId('actions', x); return `<li><div class="ll-main"><a href="#/actions/${a.id}">${a.id}</a><div>${esc(a.title)} · ${esc(pname(a.owner))}</div></div>${sbadge(a.status)}</li>`; }).join('')}</ul>` : '<p class="muted">None raised.</p>'}${(i.defects || []).length ? `<p class="mt-s">Defects: ${i.defects.map(d => `<a href="#/assets/${i.asset}?tab=defects">${d}</a>`).join(', ')}</p>` : ''}</div></div></div></div>`;
  return { title: i.id, nav: 'inspections', crumbs: [['Inspections', '#/inspections/records'], [i.id, '#']], html };
};
ACT.inspReview = (el) => { const i = byId('inspections', el.dataset.id); openModal({ title: 'Review & sign off inspection', sub: i.id, body: fld({ name: 'comment', label: 'Reviewer comment', type: 'textarea' }), buttons: [{ label: 'Sign off', cls: 'success', onClick: m => { i.status = 'Reviewed'; i.reviewer = S.ui.user; i.reviewedOn = TODAY; i.reviewComment = readForm(m).comment; log(`Reviewed inspection ${i.id}`, '#/inspections/' + i.id); save(); toast('Inspection reviewed and signed off.'); rerender(); } }] }); };

/* ---------------- Controlled, printable inspection report ---------------- */
ROUTES.print = (p) => {
  const i = byId('inspections', p[0]); if (!i) return ROUTES.notfound();
  const org = orgOf(siteOrgOf(i.site)), a = i.asset && byId('assets', i.asset);
  const counts = countBy(i.results, 'result');
  const html = `<div class="no-print btn-row mb"><a class="btn" href="#/inspections/${i.id}">← Back to inspection</a><button class="btn primary" data-act="print">${icon('print', 'sm')} Print / save as PDF</button><span class="muted">Page numbers (Page X of Y) and the controlled header appear on every printed page.</span></div>
  <div class="screen-paper print-doc"><table class="report-frame"><thead><tr><td>
    <div class="controlled-header"><div class="chh"><div class="print-logo"><div class="logo-mark">VDW</div><div><b style="font-size:12px">${esc(org.short)}</b><small>HSEQ Management System</small></div></div><div class="ch-title">${esc(i.template.title)}</div><div class="ch-meta">Document no: <b class="mono">${esc(i.template.docNumber)}</b><br>Revision no: <b>${i.template.rev}</b><br>Revision date: <b>${fmt(i.template.revDate)}</b><br>Record: <b class="mono">${i.id}</b></div></div></div>
  </td></tr></thead><tbody><tr><td>
    <div class="rep-section">Inspection details</div>
    <table class="rt"><tbody><tr><th style="width:22%">Organisation</th><td>${esc(org.name)}</td><th style="width:18%">Site</th><td>${esc(site(i.site).name)}</td></tr><tr><th>Asset / area</th><td>${esc(i.target)}${a ? ` — ${esc(a.name)}` : ''}</td><th>Serial / ID</th><td class="mono">${a ? esc(a.serial) : '—'}</td></tr><tr><th>Inspection date</th><td>${fmt(i.date)}</td><th>Inspector</th><td>${esc(pname(i.inspector))}</td></tr><tr><th>Result summary</th><td colspan="3">Pass: <b>${counts.Pass || 0}</b> · Fail: <b>${counts.Fail || 0}</b> · N/A: <b>${counts['N/A'] || 0}</b></td></tr></tbody></table>
    <div class="rep-section">Checklist results</div>
    <table class="rt"><thead><tr><th style="width:5%">#</th><th>Checklist item</th><th style="width:10%">Result</th><th style="width:35%">Comments</th></tr></thead><tbody>${i.template.questions.map((q, k) => { const r = i.results.find(x => x.qid === q.id) || {}; return `<tr class="q-row"><td>${k + 1}</td><td>${esc(q.text)}${q.critical ? ' <b>(critical)</b>' : ''}</td><td class="${r.result === 'Pass' ? 'res-pass' : r.result === 'Fail' ? 'res-fail' : 'res-na'}">${esc(r.result || '')}</td><td>${esc(r.comment || '')}${r.photo ? ` [photo: ${esc(r.photo.name)}]` : ''}</td></tr>`; }).join('')}</tbody></table>
    <div class="rep-section">Findings & corrective actions</div>
    ${i.summary ? `<p>${esc(i.summary)}</p>` : ''}
    ${i.actions.length ? `<table class="rt"><thead><tr><th>Action</th><th>Finding / required action</th><th>Owner</th><th>Due</th><th>Status</th></tr></thead><tbody>${i.actions.map(x => { const a2 = byId('actions', x); return `<tr><td class="mono">${a2.id}</td><td>${esc(a2.title)}<br><small>${esc(a2.action)}</small></td><td>${esc(pname(a2.owner))}</td><td>${fmt(a2.due)}</td><td>${esc(a2.status)}</td></tr>`; }).join('')}</tbody></table>` : '<p>No corrective actions required.</p>'}
    <div class="rep-section">Sign-off</div>
    <table class="rt"><tbody><tr><th style="width:25%">Inspector</th><td>${esc(pname(i.inspector))}</td><th style="width:15%">Date</th><td>${fmt(i.date)}</td></tr><tr><th>Reviewer</th><td>${esc(pname(i.reviewer))}</td><th>Date</th><td>${fmt(i.reviewedOn)}</td></tr></tbody></table>
    <div class="grid g2 mt-s"><div class="sign-box">Inspector signature</div><div class="sign-box">Reviewer signature</div></div>
    <p class="muted" style="font-size:10px;margin-top:10px">Generated by the VDW HSEQ Management System prototype from demonstration data. Controlled header taken from approved template ${esc(i.template.docNumber)} Rev ${i.template.rev}; electronic signatures are simulated.</p>
  </td></tr></tbody></table></div>`;
  return { title: 'Report ' + i.id, nav: 'inspections', crumbs: [['Inspections', '#/inspections/records'], [i.id, '#/inspections/' + i.id], ['Controlled report', '#']], html };
};
